`include "disciplines.vams"
`include "constants.vams"
module paper_sh_timer(in, out, count);
 inout in, out, count;
 electrical in, out, count;
 real q,n;
 analog begin
  @(initial_step) begin q=-0.25; n=0; end
  @(timer(2e-6,2e-6,1e-9)) begin q=V(in); n=n+1; end
  V(out)<+q;
  V(count)<+n;
 end
endmodule

